"""Independent packet-replay model (test only).  Deliberately different code
structure from the submission to catch implementation bugs."""
import math

def replay2(prof_cal, fab, guard, trace):
    # prof_cal: (upper, jitter) computed independently
    upper, jitter = prof_cal
    K = len(upper)
    n = fab['n']; T = fab['interval_ns']; S = fab['slice_ns']; O = fab['offset_ns']
    Q = len(fab['slices'])
    P = (Q*S)//math.gcd(T, Q*S)
    drift0 = [int(x) for x in fab['drift_ppb']]
    eff = [[drift0[i] for i in range(n)] for _ in range(P)]
    for (node, s, e, extra) in fab['heat']:
        for p in range(s, e):
            eff[p][int(node)] += int(extra)
    anch = [[False]*n for _ in range(P)]
    for (node, s, e) in fab['anchors']:
        for p in range(int(s), int(e)):
            anch[p][int(node)] = True
    links = []
    for l in fab['links']:
        e0, e1 = l['ends']
        links.append(((int(e0[0]),int(e0[1]),int(e0[2])),(int(e1[0]),int(e1[1]),int(e1[2])),
                      [int(x) for x in l['delay_ns']],[int(x) for x in l['defer_rounds']]))
    slices = [[int(x) for x in s] for s in fab['slices']]
    black = {}
    for (lid, s, e) in fab['blackouts']:
        black.setdefault(int(lid), set()).update(range(int(s), int(e)))
    hop = [[(upper[a][b]+upper[b][a])*500000 + (jitter[a]+jitter[b])*10**6 for b in range(K)] for a in range(K)]
    corr = [[(upper[a][b]-upper[b][a])*500000 for b in range(K)] for a in range(K)]
    def slice_rho(p):
        t = O + p*T
        return (t//S) % Q, t % S
    R = int(trace['rounds'])
    rates = [[int(x) for x in row] for row in trace['rates_ppb']]
    bias = [int(x) for x in trace['bias_ps']]
    lost = set(int(x) for x in trace['lost'])
    reb = {}
    for (t, node) in trace['reboots']:
        reb.setdefault(int(t), set()).add(int(node))
    queries = [int(x) for x in trace['queries']]
    sends = [(int(s[0]), int(s[1]), int(s[2]), int(s[3]), i) for i, s in enumerate(trace['sends'])]

    err = [None]*n; bnd = [None]*n; gen = [0]*n
    status = [None]*len(sends)
    inflight = []   # list of dicts
    delivered = adopted = unk = stale = pending = 0
    peak = 0
    always = True
    states = {}

    for t in range(R+1):
        # drift over interval t-1
        if t > 0:
            r = rates[t-1]
            for i in range(n):
                if err[i] is not None:
                    err[i] = err[i] + r[i]*T
                    bnd[i] = bnd[i] + eff[(t-1) % P][i]*T
                    peak = max(peak, abs(err[i]))
        for i in reb.get(t, ()):
            gen[i] += 1; err[i] = None; bnd[i] = None
        for i in range(n):
            if anch[t % P][i]:
                err[i] = 0; bnd[i] = 0
        adopted_now = [None]*n
        due = [pk for pk in inflight if pk['app'] == t]
        inflight = [pk for pk in inflight if pk['app'] != t]
        for pk in due:
            delivered += 1
            if gen[pk['src']] != pk['sg'] or gen[pk['dst']] != pk['dg']:
                stale += 1
                continue
            if not pk['known']:
                unk += 1
                continue
            e = pk['se'] + (bias[pk['gd']] - bias[pk['gs']])*10**6 + pk['jit'] - corr[pk['gs']][pk['gd']]
            b_ = pk['sb'] + hop[pk['gs']][pk['gd']]
            # receiver aging [tick*T+delay, app*T]
            aerr = 0; abnd = 0
            for k in range(pk['tick'], pk['app']):
                lo = max(k*T, pk['tick']*T + pk['delay'])
                hi = min((k+1)*T, pk['app']*T)
                if hi > lo:
                    aerr += rates[k][pk['dst']]*(hi-lo)
                    abnd += eff[k % P][pk['dst']]*(hi-lo)
            pk['ce'] = e + aerr
            pk['cb'] = b_ + abnd
        # adoption: best per receiver
        best = {}
        for pk in due:
            if 'cb' not in pk: continue
            cur = best.get(pk['dst'])
            if cur is None or (pk['cb'], pk['id']) < (cur['cb'], cur['id']):
                best[pk['dst']] = pk
        for dst, pk in best.items():
            if bnd[dst] is None or pk['cb'] < bnd[dst]:
                bnd[dst] = pk['cb']; err[dst] = pk['ce']
                adopted_now[dst] = pk['id']; adopted += 1
                peak = max(peak, abs(err[dst]))
        if any(err[i] is None for i in range(n)):
            always = False
        if t in set(queries):
            states[t] = {'bounds_as': [bnd[i] for i in range(n)],
                         'errors_as': [err[i] for i in range(n)],
                         'adopted': list(adopted_now),
                         'generations': [gen[i] for i in range(n)]}
        # sends
        batch = sorted([s for s in sends if s[1] == t])
        used = set()
        for (pid, _tk, code, jit, idx) in batch:
            l = code//2; d = code % 2
            (n0,s0,g0),(n1,s1,g1),delays,defers = links[l]
            src,dst,gs,gd = (n0,n1,g0,g1) if d == 0 else (n1,n0,g1,g0)
            sli, rho = slice_rho(t % P)
            if l not in slices[sli]:
                status[idx] = 'not_in_slice'; continue
            delay = delays[d]
            m = (delay + T - 1)//T
            blocked = False
            for j in range(m):
                if ((t % P) + j) % P in black.get(l, ()):
                    blocked = True
            if blocked:
                status[idx] = 'blackout'; continue
            if not (rho >= guard and rho + delay + guard <= S):
                status[idx] = 'guard'; continue
            port = (src, s0 if d == 0 else s1)
            if port in used:
                status[idx] = 'port_busy'; continue
            used.add(port)
            if pid in lost:
                status[idx] = 'lost'; continue
            status[idx] = 'sent'
            dt = m + defers[d]
            pk = {'id': pid, 'src': src, 'dst': dst, 'gs': gs, 'gd': gd,
                  'delay': delay, 'tick': t, 'app': t + dt, 'jit': jit,
                  'known': err[src] is not None,
                  'se': err[src], 'sb': bnd[src],
                  'sg': gen[src], 'dg': gen[dst]}
            if pk['app'] > R:
                pending += 1
            else:
                inflight.append(pk)
    return {"status": "ok", "states": [states[t] for t in queries],
            "send_status": status, "delivered": delivered, "adopted": adopted,
            "unknown_payloads": unk, "stale_payloads": stale,
            "pending": pending, "peak_known_abs_as": peak,
            "always_known": always}
EOF
